def prime_factors(*args, **kwargs):
    if not args:
        raise ValueError("Missing argument")
    n = args[0]
    if n < 2:
        raise ValueError("Input must be >= 2")
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors
